 float raw(const juce::String& suffix)const{auto id=fxId(e.slot,suffix);float value=p.value(id);auto links=p.macros();if(auto* link=links->find(id))value=link->parameter->convertFrom0to1(link->normalized(p.value("macro"+juce::String(link->macro+1))));return value;}
