 void text(juce::Graphics& g,juce::String s,juce::Rectangle<float> r,float size=9,juce::Colour colour=nd::colour(juce::Colour(0xff8ea6b8)))const{g.setColour(nd::colour(colour));g.setFont(juce::FontOptions(nd::number("fontSize",size),juce::Font::bold));g.drawText(s,r,juce::Justification::centredLeft,false);}
 void node(juce::Graphics& g,juce::Point<float> point,int number=-1)const{g.setColour(nd::colour(nd::colour(juce::Colour(0xff0b1520))));g.fillEllipse(point.x-4,point.y-4,8,8);g.setColour(nd::colour(accent));g.drawEllipse(point.x-4,point.y-4,8,8,1.4f);if(number>=0)text(g,juce::String(number),{point.x+6,point.y-9,24,15},9,accent);}
 void grid(juce::Graphics& g,juce::Rectangle<float> r,bool frequency=true)const{if(!frequency){g.setColour(nd::colour(accent.withAlpha(.18f)));g.drawHorizontalLine(juce::roundToInt(r.getCentreY()),r.getX(),r.getRight());return;}g.setColour(nd::colour(nd::colour(juce::Colour(0xff21333f)).withAlpha(.55f)));if(frequency)for(float hz:{50.f,100.f,250.f,500.f,1000.f,2000.f,5000.f,10000.f}){float x=hzX(hz,r);if(x<r.getRight())g.drawVerticalLine(juce::roundToInt(x),r.getY(),r.getBottom());}else for(int i=1;i<8;++i)g.drawVerticalLine(juce::roundToInt(r.getX()+i*r.getWidth()/8),r.getY(),r.getBottom());for(int i=1;i<4;++i)g.drawHorizontalLine(juce::roundToInt(r.getY()+i*r.getHeight()/4),r.getX(),r.getRight());}
 void trace(juce::Graphics& g,juce::Rectangle<float> r,const std::array<float,1024>& samples,juce::Colour colour,bool envelope=false)const{juce::Path path;for(int i=0;i<256;++i){float value=samples[(size_t)i*4];if(envelope){value=0;for(int k=0;k<4;++k)value=juce::jmax(value,std::abs(samples[(size_t)i*4+k]));}float x=r.getX()+i/255.f*r.getWidth(),y=envelope?r.getBottom()-juce::jlimit(0.f,1.f,value*2)*r.getHeight():r.getCentreY()-juce::jlimit(-1.f,1.f,value)*r.getHeight()*.48f;if(i==0)path.startNewSubPath(x,y);else path.lineTo(x,y);}g.setColour(nd::colour(colour));g.strokePath(path,juce::PathStrokeType(nd::number("stroke",1.1f)));}
