 std::complex<float> biquad(const std::array<float,6>& c,float hz)const{auto z=std::polar(1.f,-juce::MathConstants<float>::twoPi*hz/rate());return (c[0]+c[1]*z+c[2]*z*z)/(c[3]+c[4]*z+c[5]*z*z);}
