 template<class Fn>void curve(juce::Graphics& g,juce::Rectangle<float> r,Fn fn,float lo=-24,float hi=24)const{juce::Path path;for(int i=0;i<240;++i){float hz=xHz(r.getX()+i/239.f*r.getWidth(),r),db=juce::Decibels::gainToDecibels(fn(hz),-90.f),x=r.getX()+i/239.f*r.getWidth(),y=dbY(db,r,lo,hi);if(i==0)path.startNewSubPath(x,y);else path.lineTo(x,y);}UiStyle::fillCurve(g,path,r,dbY(0,r,lo,hi),accent);g.setColour(nd::colour(accent));g.strokePath(path,juce::PathStrokeType(nd::number("stroke",1.5f)));}
