 void filter(juce::Graphics& g,juce::Rectangle<float> r){grid(g,r);spectrum(g,r);auto links=p.macros();if(auto* link=links->find(fxId(e.slot,"p0"))){auto def=fxDefinitions()[(size_t)e.type].controls[0];float x1=hzX(def.from(link->start),r),x2=hzX(def.from(link->end),r);g.setColour(nd::colour(juce::Colour(links->colours[link->macro]).withAlpha(.15f)));g.fillRect(juce::Rectangle<float>(juce::jmin(x1,x2),r.getY(),std::abs(x2-x1),r.getHeight()));}curve(g,r,[&](float hz){return filterMagnitude(hz,v(0),v(1),juce::roundToInt(v(2)));},-36,18);float x=hzX(v(0),r);g.setColour(nd::colour(accent.withAlpha(.45f)));g.drawVerticalLine(juce::roundToInt(x),r.getY(),r.getBottom());node(g,{x,r.getBottom()-v(1)/.95f*r.getHeight()});juce::StringArray names{"LP","HP","BP","NOTCH"};for(int k=0;k<4;++k){g.setColour(nd::colour(accent.withAlpha(juce::roundToInt(v(2))==k?.3f:.07f)));g.fillRect(r.getX()+k*51,r.getBottom()+2,47.f,14.f);text(g,names[k],{r.getX()+5+k*51,r.getBottom()+2,42,14},8,accent);}}
