 float shape(float x)const{if(raw("customShape")>.5f){float at=(x+1)*8;int k=juce::jmin(15,(int)at);return raw("shape"+juce::String(k))*(1-(at-k))+raw("shape"+juce::String(k+1))*(at-k);}x*=juce::Decibels::decibelsToGain(v(0));int mode=juce::roundToInt(v(1));if(mode==0)return std::tanh(x);if(mode==1)return juce::jlimit(-1.f,1.f,x);if(mode==2)return x/(1+std::abs(x));if(mode==3)return 2*std::abs(2*((x+1)/4-std::floor((x+1)/4+.5f)))-1;return std::round(juce::jlimit(-1.f,1.f,x)*16)/16;}
 void distortion(juce::Graphics& g){auto r=shaperRect();grid(g,r,false);juce::Path path;for(int i=0;i<180;++i){float x=-1+i/179.f*2,y=shape(x);auto at=juce::Point<float>(r.getX()+i/179.f*r.getWidth(),r.getCentreY()-y*r.getHeight()*.5f);if(i==0)path.startNewSubPath(at);else path.lineTo(at);}UiStyle::fillCurve(g,path,r,r.getCentreY(),accent);g.setColour(nd::colour(accent));g.strokePath(path,juce::PathStrokeType(nd::number("stroke",1.5f)));if(raw("customShape")>.5f)for(int i=0;i<17;++i)node(g,{r.getX()+i/16.f*r.getWidth(),r.getCentreY()-raw("shape"+juce::String(i))*r.getHeight()*.5f});auto all=plot(),f=shapeFilterRect();juce::Rectangle<float> wave(all.getX()+all.getWidth()*.55f,all.getY(),all.getWidth()*.45f,all.getHeight()*.44f);trace(g,wave,input,nd::colour(juce::Colour(0xff718395)));trace(g,wave,output,accent);grid(g,f);spectrum(g,f);curve(g,f,[&](float hz){auto pre=raw("preCut")>=19999?std::complex<float>(1):pole(hz,raw("preCut"));return std::abs(pre*pole(hz,v(2)));},-36,3);node(g,{hzX(raw("preCut"),f),f.getY()+4});node(g,{hzX(v(2),f),f.getCentreY()});text(g,"PRE / POST FILTER + OUTPUT SPECTRUM",{f.getX(),f.getBottom()+1,f.getWidth(),12},7);for(int k=0;k<2;++k){juce::Rectangle<float> button((float)getWidth()-116+k*55,3,51,15);g.setColour(nd::colour(accent.withAlpha((raw("customShape")>.5f)==(k==1)?.25f:.07f)));g.fillRect(button);text(g,k==0?"MODES":"DRAW",button.translated(4,0),8,accent);}}
 float echoTime()const{int sync=juce::roundToInt(v(5));float beats[]={0,.25f,.5f,1,2,4,8};float maximum=(std::floor(rate()*2.2f)+2)/rate()*1000;return juce::jlimit(1.f,maximum,sync?beats[juce::jlimit(1,6,sync)]*60000/data().tempo.load():v(0));}
 juce::Rectangle<float> delayFilter()const{auto r=plot();return {r.getX(),r.getBottom()-17,r.getWidth(),17};}
 void delay(juce::Graphics& g,juce::Rectangle<float> r){auto timeline=r.withHeight(r.getHeight()-23);grid(g,timeline,false);float first=echoTime(),window=juce::jmax(1000.f,first*4),spacing=first/window*r.getWidth();for(int lane=0;lane<2;++lane){float cy=timeline.getY()+timeline.getHeight()*(lane==0?.25f:.75f);text(g,lane==0?"L":"R",{r.getX(),cy-7,15,14},8,accent);for(int repeat=1;repeat<=10;++repeat){float x=r.getX()+repeat*spacing;if(x>r.getRight())break;float cross=(repeat%2==lane?1.f:1-v(2)),gain=std::pow(v(1),(float)repeat-1)*cross;if(gain<.001f&&repeat>1)continue;g.setColour(nd::colour(accent.withAlpha(.3f+.65f*gain)));g.drawVerticalLine(juce::roundToInt(x),cy-gain*timeline.getHeight()*.21f,cy+gain*timeline.getHeight()*.21f);if(repeat==1)node(g,{x,cy});}}auto f=delayFilter();curve(g,f,[&](float hz){return cutMagnitude(hz,v(3),v(4));},-30,3);node(g,{hzX(v(3),f),f.getCentreY()});node(g,{hzX(v(4),f),f.getCentreY()});text(g,juce::String(first,0)+" ms  /  "+juce::String(data().tempo.load(),1)+" BPM",{r.getX(),r.getBottom()+2,200,14},8);text(g,"drag echo / filter handles",{r.getRight()-180,r.getBottom()+2,180,14},8);}

