 void spread(juce::Graphics& g,juce::Rectangle<float> r){grid(g,r,false);int voices=e.type==9?7:4;float phase=data().phase.load()*juce::MathConstants<float>::twoPi,depth=v(1),wet=raw("wet");for(int voice=0;voice<voices;++voice){juce::Path wave;float shift=(voice-(voices-1)*.5f)*depth*4;for(int i=0;i<180;++i){int sample=(i*5+(int)(phase*20+voice*depth*30))%1024;float y=r.getCentreY()+shift-output[(size_t)sample]*r.getHeight()*.5f;float x=r.getX()+i/179.f*r.getWidth();if(i==0)wave.startNewSubPath(x,y);else wave.lineTo(x,y);}g.setColour(nd::colour(accent.withAlpha(.1f+.65f*wet/((std::abs(voice-voices/2)+1)*.5f))));g.strokePath(wave,juce::PathStrokeType(nd::number("stroke",1)));}float width=e.type==9?juce::jlimit(0.f,1.f,v(5)*.5f*(.5f+.5f*v(4))*(.6f+.4f*v(3)/40)):depth;g.setColour(nd::colour(accent.withAlpha(.35f)));g.drawHorizontalLine(juce::roundToInt(r.getBottom()-4),r.getCentreX()-width*r.getWidth()*.45f,r.getCentreX()+width*r.getWidth()*.45f);for(int voice=0;voice<voices;++voice){float x=r.getCentreX()+(voice/(float)(voices-1)-.5f)*width*r.getWidth()*.9f;g.setColour(nd::colour(accent));g.fillEllipse(x-2,r.getBottom()-6,4,4);}text(g,"STEREO SPREAD / SCHEMATIC",{r.getX(),r.getBottom()+2,240,14},8);text(g,"corr "+juce::String(data().correlation.load(),2),{r.getRight()-80,r.getBottom()+2,80,14},8);}
