 float compression(float db,float threshold)const{float above=db-threshold,knee=raw("knee");if(knee>0&&above>-knee*.5f&&above<knee*.5f)return db-(1-1/v(1))*std::pow(above+knee*.5f,2.f)/(2*knee)+v(4);return db-juce::jmax(0.f,above)*(1-1/v(1))+v(4);}
